-- Sovietski: the Novyet N-1051 Volkhov and N-1082 Sadko ekranoplans and the SUMi-185 Red Squall (printed 169-176).
-- 3 vehicle rows, with 28 locations and 10 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~385-sovietski-v1.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('novyet-n-1051-volkhov-ekranoplan', 'Novyet N-1051 Volkhov Light Transport Ekranoplan', 'rifts', 'vehicle', '6-10: pilot, co-pilot, navigator, comms officer and two stewards for the cargo or passengers; two more can squeeze into the cockpit. A combat conversion adds two gunners. Passenger craft may add up to four stewards, cargo craft 4-8 heavy cyborgs as loaders.', 'Any mix of troops, from 60 foot soldiers plus 20 Light or Heavy Machines up to a full company of 60 Heavy and Superheavy Machines.', 'No driving. Its ground-effect flight works over flat, open tundra or ice as well as water (see air speed).', 'Ground-effect flight alone, at a height of 10 to 30 feet (3-9.1 m) over a flat surface and never above it: 350 mph (560 km) top, 250 mph (400 km) cruising, ceiling 30 feet (9.1 m). Range 1,100 miles (1,760 km) on diesel turbofans, effectively unlimited on nuclear, but only where the surface is flat.', 'Surface 75 mph (120 km); 50 mph (80 km) with one engine lost, 15 mph (24 km) with two. Cannot submerge.', 'Height 48 feet (14.6 m), wingspan 96 feet (29.2 m), length 158 feet (48.1 m).', '116 tons; carries 120 tons of cargo', 250, 1, NULL, 6000000, 'Open market: 6 million credits with a diesel engine, 8.3 million nuclear. The Sovietski pays 3.5 million (diesel) or 5.7 million (nuclear) through its bulk discount.', 'A compact Novyet ground-effect craft: a stubby-winged, jet-transport-shaped hull with turboprops that floats like a boat at rest and, once up to speed, skims a few yards above calm water, ice or open tundra on a cushion of compressed air. That cushion lets it haul far more than an aircraft of its size and outrun any ship, but it cannot climb, turns poorly (it lands to come about or makes a wide loop), and is grounded by waves over 10 feet (3 m), winds above 45 mph (72 km) or any broken terrain, so crews keep within about 100 miles (160 km) of the coast. Flying so low also lets it slip under some radar while leaving it in reach of Gargoyles and dragons. Named for the river princess of Russian legend. The Sovietski uses most of them to move troops and cargo along its coasts; Novyet sells it to anyone. Civilian models carry no weapons as standard; the Sovietski is fitting some with a rail gun and missiles (the weapons listed). Diesel or nuclear power, 12-year life. Each crewman gets a locker; aboard are four foldout bunks, six bedrolls, first aid supplies, 227 liters (60 gallons) of water, a week of rations, and a weapons locker with flare guns and flares, two signal smoke grenades, four handguns, eight rifles and jet packs for crew, cyborgs and escorts. It has the standard Sovietski vehicle systems and an I.F.F. transponder, but no Cyberlink and no Gromeko Friend or Foe system.', 'Rifts World Book 36: Sovietski p.169-172'),
  ('novyet-n-1082-sadko-ekranoplan', 'Novyet N-1082 Sadko Heavy Transport Ekranoplan', 'rifts', 'vehicle', '10-14: pilot, co-pilot, navigator, comms officer, two gunners (four on a military craft) and four stewards; sometimes an intelligence or science officer, and a weapons systems expert on a missile craft. Passenger craft may add up to four stewards, cargo craft 8-10 heavy cyborgs as loaders.', 'Up to 800 equipped human soldiers in cramped conditions, or 400 plus 24 light vehicles such as hovercycles, jeeps or snowmobiles, or 700 tons of cargo including armored vehicles. In cyborgs: 700 Light Machines, 540 Heavy Machines or 280 Superheavy Machines.', 'No driving. Its ground-effect flight works over flat, open tundra or ice as well as water (see air speed).', 'Ground-effect flight only, never higher than 20 feet (6 m): 400 mph (640 km) top, 330 mph (528 km) cruising. Range 2,600 miles (4,160 km) on diesel turbofans, effectively unlimited on nuclear, but only where the surface is flat.', 'Surface 75 mph (120 km); 50 mph (80 km) with half the engines lost, 20 mph (32 km) with only two left. Cannot submerge.', 'Height 90 feet (27.4 m), wingspan 164 feet (50 m), length 380 feet (116 m).', '385 tons; carries 700 tons of cargo', 500, 1, NULL, 38000000, '38 million credits with a diesel engine, 50 million nuclear. The Sovietski gets 20% off.', 'The largest and fastest ekranoplan ever built, which industry experts reckon is as far as ground effect can usefully be pushed. Modeled on the old MD-160 Lun, it carries eight big jet engines in a row on a canard above and behind the cockpit, so it needs no rear engine. Mainly a sea transport, too big for all but a few lakes and rivers. Named for the merchant-musician of legend who bargained with the Sea Tsar. The Sovietski runs two dozen: eight at New Leningrad, four at Kaliningrad, two at the Volga Fortress for the river and the Caspian, and the rest in dry dock for combat repairs. Its runs across the stormy Baltic are Kaliningrad''s fastest supply line. Warlord Romanov buys them cheaply because Novyet works under her protection; both the NGR and the Free Scandinavian Alliance have shown interest but bought none. Ground-effect limits as for the Volkhov: calm, flat surfaces only, wide turns, within about 100 miles (160 km) of shore. Diesel or nuclear power, 12-year life. Carries the Volkhov''s crew stores plus four sets of Red Star armor and food and water for 15 days. Civilian craft come armed with two laser ball turrets and a rail gun; the military missile platform adds mini-missiles and six short-range launch tubes. Only one craft has the missile refit so far, as a demonstration, and any other can be converted in 1D4+1 weeks. Standard Sovietski vehicle systems and an I.F.F. transponder, but no Cyberlink and no Gromeko Friend or Foe system.', 'Rifts World Book 36: Sovietski p.169-174'),
  ('sumi-185-red-squall', 'SUMi-185 Red Squall VTOL Assault Platform', 'rifts', 'vehicle', 'One pilot, a human or a Light Machine.', 'None.', 'None. It rolls on three wheels when pushed but cannot drive itself.', '300 mph (480 km), with one-melee (15 second) sprints to 490 mph (784 km) up to six times per hour; cruise 80-150 mph (128-240 km). Hovers and takes off and lands vertically. Ceiling 6,000 feet (1,829 m).', 'None.', 'Height 7 feet (2.1 m). Width 6 feet (1.8 m) with the wings folded, 18 feet (5.5 m) spread. Length 10 feet (3 m) with the tail retracted, 21 feet (6.4 m) extended.', '1.7 tons with a full weapon load', 160, 1, NULL, 3000000, 'Black Market only, at 3-4 million credits, and extremely rare there.', 'A tiny one-seat VTOL gunship flown by Sovietski military and police for rapid response, and seen almost everywhere in the Sovietski. It looks like a cross between a miniature helicopter and a Coalition rocket bike: engines, short wings, a Y tail and a weapon-laden nose, with the pilot in an open seat behind a small M.D.C. windscreen, locked in by an armored chest harness and jacked in by Cyberlink. The pilot is hard to hit from below or behind: only a Called Shot with line of sight can reach him, at -4 to strike, and he is expected to wear body armor or be a cyborg. Flown without a Cyberlink it suffers -20% to piloting, a further -10% on evasive moves, stunts and crash landings, -1 attack per melee, -2 strike and -3 dodge, since its manual controls are minimal. Wings and tail fold so it fits in a pickup bed; sixteen fit a 15.2 m (50 foot) trailer and a hundred a Sadko ekranoplan, and Storm Swell ships, Tunguska super-tanks and Stormbringer gunships carry them, the last dropping them from the air. Losing one wing or the tail does not down it but costs 40% speed, -20% piloting and -2 dodge; a wing and the tail together cost 80% of speed and altitude, -35% piloting and -5 dodge. A storage space behind the seat takes a rifle, sidearm, canteen and pack, and 200 pounds (90 kg) more can be netted to the hull. Nuclear, 15-year life. It has the standard Sovietski sensors plus a radar detector that identifies Warlord, Sovietski, NGR and Brodkil radars. A utility version swaps the nose gun for a crane arm and winch (500 lb/225 kg lift, flown at half speed and half altitude with no sprints) for rescue and light supply drops, and may swap the missile launchers for medical kits and a long-range sensor suite; the lasers always stay.', 'Rifts World Book 36: Sovietski p.169-176');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('novyet-n-1051-volkhov-ekranoplan', 'Wings (2)', 85, 'Each.', 1),
  ('novyet-n-1051-volkhov-ekranoplan', 'Tail', 50, NULL, 2),
  ('novyet-n-1051-volkhov-ekranoplan', 'Wing Turboprop Engines (2)', 120, 'Each. Losing any one engine keeps the craft from reaching ground effect: it can still maneuver in the water but cannot fly.', 3),
  ('novyet-n-1051-volkhov-ekranoplan', 'Rear Tail Turboprop', 80, NULL, 4),
  ('novyet-n-1051-volkhov-ekranoplan', 'Rail Gun (1; nose)', 75, 'Sovietski military vehicles only.', 5),
  ('novyet-n-1051-volkhov-ekranoplan', 'Mini-Missile Launchers (2)', 35, 'Each. Sovietski military vehicles only.', 6),
  ('novyet-n-1051-volkhov-ekranoplan', 'Main Body', 250, 'Depleting it destroys the vehicle.', 7),
  ('novyet-n-1082-sadko-ekranoplan', 'Forward Canards (2)', 45, 'Each.', 1),
  ('novyet-n-1082-sadko-ekranoplan', 'Wings (2)', 140, 'Each.', 2),
  ('novyet-n-1082-sadko-ekranoplan', 'Tail', 120, NULL, 3),
  ('novyet-n-1082-sadko-ekranoplan', 'Engines (8)', 100, 'Each. Losing three or more keeps it from reaching ground effect: it can still maneuver in the water but cannot fly.', 4),
  ('novyet-n-1082-sadko-ekranoplan', 'Laser Turrets (2)', 100, 'Each.', 5),
  ('novyet-n-1082-sadko-ekranoplan', 'Wingtip Rail Guns (2)', 75, 'Each. The weapon text describes one top-mounted SRG-200 rail gun instead; the table and the commercial-weapons lead-in say wingtip rail guns.', 6),
  ('novyet-n-1082-sadko-ekranoplan', 'Mini-Missile Launchers (2)', 35, 'Each. Military craft only.', 7),
  ('novyet-n-1082-sadko-ekranoplan', 'Missile Launch Tubes (6)', 100, 'Each. Military missile-platform craft only.', 8),
  ('novyet-n-1082-sadko-ekranoplan', 'Main Body', 500, 'Depleting it destroys the vehicle.', 9),
  ('sumi-185-red-squall', 'Wings (2)', 70, 'Each.', 1),
  ('sumi-185-red-squall', 'Tail Section', 75, NULL, 2),
  ('sumi-185-red-squall', 'Main VTOL Engine', 70, NULL, 3),
  ('sumi-185-red-squall', 'Jet Engines (2)', 50, 'Each. Small target: Called Shot only, -4 to strike.', 4),
  ('sumi-185-red-squall', 'Wheels (3)', 3, 'Each; one in each wing and one under the tail. Small target: Called Shot only, -4 to strike.', 5),
  ('sumi-185-red-squall', 'Nose Rail Gun', 100, NULL, 6),
  ('sumi-185-red-squall', 'Wing Mini-Missile Launchers (2)', 35, 'Each.', 7),
  ('sumi-185-red-squall', 'Wing Lasers (2)', 20, 'Each; inner wing, one per side. Small target: Called Shot only, -4 to strike.', 8),
  ('sumi-185-red-squall', 'Sensor Dome (top)', 15, 'Small target: Called Shot only, -4 to strike. Losing it knocks out long-range communications, radar and other sensors.', 9),
  ('sumi-185-red-squall', 'Sensor Sphere (nose)', 12, 'Small target: Called Shot only, -4 to strike. Losing it takes the nose camera, optics and targeting: the pilot loses his piloting and feature bonuses and is -3 to strike and dodge.', 10),
  ('sumi-185-red-squall', 'Pilot Harness and Shielding', 35, 'Small target: Called Shot only, -4 to strike. Once it is gone, hits go to the pilot''s own armor or body, and with only a lap belt he has a 01-33% chance of being thrown out in stunts, a crash or a single hit over 60 M.D.; if he is, the aircraft crashes.', 11),
  ('sumi-185-red-squall', 'Main Body', 160, 'Depleting it shuts the vehicle down; in flight, it crashes.', 12);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('novyet-n-1051-volkhov-ekranoplan', 1, 'SRG-200 Rail Gun', 'Short 10-round burst 3D6 M.D.; full 40-round burst 1D6x10 M.D.', 1, '4,000 feet (1,219 m)', 'Each burst counts as one melee attack.', '12,000-round drum: 300 full bursts or 1,200 short ones. A reload takes 20 minutes, or six with an engineering or field armorer skill.', NULL, 'Sovietski military vehicles only. Top-mounted behind the cockpit, fired remotely by the main gunner; turns 360 degrees with a 45-degree arc up and down. Anti-aircraft first, then anti-personnel and defense.'),
  ('novyet-n-1051-volkhov-ekranoplan', 2, 'Mini-Missile Launchers (2)', 'Plasma mini-missiles as standard, 1D6x10 M.D. each; any mini-missile type can be loaded', 1, 'One mile (1.6 km)', 'Singly or in volleys of 2 or 4.', '16: eight per wing launcher. One full reload of 32 is carried aboard; reloading is by hand after landing, one minute per missile.', NULL, 'Sovietski military vehicles only. Low-profile launchers on the wings beside the fuselage, aimed forward and able to angle 30 degrees outward; the secondary gunner fires them. Against flyers and missiles, then ships and defense.'),
  ('novyet-n-1051-volkhov-ekranoplan', 3, 'Short-Range Missile Launchers (2)', 'Typically medium high explosive, 2D6x10 M.D. per missile; varies by missile type (Rifts Ultimate Edition p.363)', 1, '5 miles (8 km)', 'One at a time or a volley of 2.', 'Two, one per launcher, plus four spares stowed aboard. Reloading needs the craft stopped and a cyborg of Robotic P.S. 25 or more, 1D4+2 minutes per missile.', NULL, 'Sovietski military vehicles only. One on each side of the tail base under the turboprop, fired by the secondary gunner. Anti-aircraft, then anti-armor. The M.D.C. table gives them no location of their own.'),
  ('novyet-n-1082-sadko-ekranoplan', 1, 'Laser Turrets (2)', '6D6 M.D. per dual blast; the paired lasers cannot fire separately', 1, '3,000 feet (914 m)', 'Commercial craft: each blast counts as one melee attack. Military craft: equal to the gunner''s combined hand to hand attacks.', 'Effectively unlimited.', NULL, 'On every Sadko. Ball turrets in the nose and at the tail base, each with two fire-linked heavy lasers, 270 degrees of forward-facing rotation and a 60-degree arc up and down; a gunner sits inside each. Anti-aircraft and anti-missile, then defense.'),
  ('novyet-n-1082-sadko-ekranoplan', 2, 'SRG-200 Rail Gun', 'Short 10-round burst 3D6 M.D.; full 40-round burst 1D6x10 M.D.', 1, '4,000 feet (1,219 m)', 'Each burst counts as one melee attack.', 'Commercial craft: 12,000-round drum, 300 full bursts or 1,200 short. Military craft: 20,000-round drum, 500 full bursts or 2,000 short. A reload takes 20 minutes, or six with Engineering or Field Armorer skill.', NULL, 'On every Sadko. Top-mounted behind the cockpit, fired remotely by the main gunner; 360-degree rotation, 45-degree arc up and down. Anti-aircraft, then anti-personnel and defense. The M.D.C. table lists Wingtip Rail Guns (2) instead.'),
  ('novyet-n-1082-sadko-ekranoplan', 3, 'Mini-Missile Launchers (2)', 'Standard: armor piercing (1D4x10 M.D.), plasma (1D6x10 M.D.) or a mix of the two; any mini-missile type can be loaded', 1, 'One mile (1.6 km)', 'Singly or in volleys of 2 or 4.', '16: eight per wing launcher. Two full reloads of 32 are carried aboard; reloading is by hand after landing, one minute per missile.', NULL, 'Military craft only. Low-profile launchers on the wings beside the fuselage, aimed forward and able to angle 30 degrees outward; the secondary gunner fires them. Against flyers and missiles, then ships and defense.'),
  ('novyet-n-1082-sadko-ekranoplan', 4, 'Short-Range Missile Launchers (6)', 'By missile type. Standard load: 6 light high explosive (2D4x10 M.D., 10 foot/3 m blast radius), 6 heavy high explosive (2D6x10 M.D., 15 foot/4.6 m radius) and 12 plasma (2D6x10 M.D., 15 foot/4.6 m radius)', 1, '5 miles (8 km)', 'Single shots, or volleys of 2, 4 or 6.', '24, four per tube, plus 24 spares stowed aboard. Reloading needs the craft stopped and cyborgs of Robotic P.S. 25 or more, one missile at a time, 1D4+1 minutes each.', NULL, 'Military missile-platform craft only. Three pairs of tubes along the top of the hull, angled 15 degrees up and forward, fired by a dedicated gunner. Anti-aircraft and anti-missile, then anti-ship and anti-Gargoyle.'),
  ('sumi-185-red-squall', 1, 'Precision Heavy Rail Gun (nose)', 'Armor piercing round: 4D6 M.D. Fragmentation round: 2D6 M.D. across a 6 foot (1.8 m) diameter', 1, '4,000 feet (1,219 m)', 'Single shots only; each counts as one melee attack.', '80-round divided magazine: 40 of each type, or 80 of one.', '+1 strike with Aimed or Called Shots.', 'Anti-cyborg and anti-armor, then anti-personnel. The utility version replaces it with a crane arm.'),
  ('sumi-185-red-squall', 2, 'Dual Lasers (2)', '2D6 M.D. single blast, 4D6 M.D. double blast', 1, '2,000 feet (610 m)', 'A single or a double blast uses one melee attack.', 'Effectively unlimited.', NULL, 'A light laser at each wing root, fired singly or together. For strafing and anti-personnel work, dogfighting and defense, or when other ammunition runs low. A permanent fitting on every version.'),
  ('sumi-185-red-squall', 3, 'Mini-Missile Launchers (1 per wing)', 'Standard load: 9 plasma (1D6x10 M.D.), 9 armor piercing (1D4x10 M.D.), 2 smoke; any type can be loaded. For riot control: 12 tear gas, 6 smoke and 2 high explosive', 1, 'One mile (1.6 km)', 'Single shots, or volleys of 2, 3, 5 or 10.', '20: ten per wing launcher. (The launcher description calls each a five-shot launcher; the payload line and the standard load both count 20.)', NULL, 'Under each wing. Anti-cyborg and anti-tank, then anti-missile and anti-aircraft. The utility version may swap them for medical kits and a long-range sensor suite.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('novyet-n-1051-volkhov-ekranoplan', 'novyet-n-1082-sadko-ekranoplan', 'sumi-185-red-squall');
SELECT 'their 28 locations are in' AS assertion, count(*) AS got, 28 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('novyet-n-1051-volkhov-ekranoplan', 'novyet-n-1082-sadko-ekranoplan', 'sumi-185-red-squall');
SELECT 'their 10 weapon entries are in' AS assertion, count(*) AS got, 10 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('novyet-n-1051-volkhov-ekranoplan', 'novyet-n-1082-sadko-ekranoplan', 'sumi-185-red-squall');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('novyet-n-1051-volkhov-ekranoplan', 'novyet-n-1082-sadko-ekranoplan', 'sumi-185-red-squall') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

